item.content:encoded:
#nav {
    padding-top: 10px;
    background-image: url(https://bfmg.maths.coventry.domains/wp-content/uploads/2023/03/Hypertiling_new-e1678749319411.jpg);
}

#wrapper {
    width: 1200px; max-width:1200px
}
#content {
    width: 820px; /* If you increase the wrapper, increase this too */
}



/* 3. Ensure images fill the new width */
#content img {
    max-width: 100%;
    height: auto;
}

/* 4. Adjust the Header/Footer to match the new width */
#header, #footer {
    width: 1200px;
}
